    private BotnaArabicDialect() { }

    public static String normalize(String raw) {
        String value = raw == null ? "" : raw.trim().toLowerCase(Locale.ROOT);
        value = value.replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا').replace('ٱ', 'ا').replace('ى', 'ي').replace('ـ', ' ');
        String arabicDigits = "٠١٢٣٤٥٦٧٨٩";
        for (int i = 0; i < arabicDigits.length(); i++) value = value.replace(arabicDigits.charAt(i), (char) ('0' + i));
        value = value.replaceAll("[\\u064B-\\u065F\\u0670]", "");
        for (String[] pair : NORMALIZATIONS) {
            String regex = "(?<![\\p{L}\\p{N}])" + Pattern.quote(pair[0]) + "(?![\\p{L}\\p{N}])";
            value = value.replaceAll(regex, java.util.regex.Matcher.quoteReplacement(pair[1]));
        }
        value = value.replaceAll("^(?:(?:بدي|بدّي|ممكن|يا ريت|ياريت)\\s+)+", "");
        return value.replaceAll("[\\u064B-\\u065F\\u0670]", "").replaceAll("\\s+", " ").trim();
    }

